<?php if(!$selected||$selected['status']!=='archived'):?><section class="panel"><h2><?=h($label($selected?'saved_search.edit':'saved_search.save'))?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$selectedId??''?>">
