<label class="field"><?=h($label('saved_search.origin_country'))?><select name="origin_country"><?php foreach($countries as $code=>$name):?><option value="<?=h($code)?>" <?=$values['origin_country']===$code?'selected':''?>><?=h($name)?></option><?php endforeach;?></select></label><label class="field"><?=h($label('Bezugs-Postleitzahl'))?><input name="zip" maxlength="16" value="<?=h($values['zip'])?>"></label><label class="field"><?=h($label('Radius in km'))?><input name="radius_km" type="number" min="1" max="2000" value="<?=h($values['radius_km'])?>"></label>
<label class="field"><?=h($label('Sortierung'))?><select name="sort"><?php foreach(['relevance'=>'classification.relevance','newest'=>'Neueste zuerst','price_asc'=>'Preis aufsteigend','price_desc'=>'Preis absteigend','ending'=>'Bald endende Auktionen','distance'=>'Nächste zuerst'] as $value=>$name):?><option value="<?=h($value)?>" <?=$values['sort']===$value?'selected':''?>><?=h($label($name))?></option><?php endforeach;?></select></label>
